import{_ as a,o as i,c as t,a2 as e}from"./chunks/framework.mRCPFc5l.js";const c=JSON.parse('{"title":"插件能安装却不能保存：宿主接口与版本兼容","description":"从一个桌面主题扩展的近期迁移，梳理宿主契约、保存确认、peerDependencies、预发布版本和打包产物之间的关系。","frontmatter":{"title":"插件能安装却不能保存：宿主接口与版本兼容","description":"从一个桌面主题扩展的近期迁移，梳理宿主契约、保存确认、peerDependencies、预发布版本和打包产物之间的关系。"},"headers":[],"relativePath":"practice/plugin-host-compatibility.md","filePath":"practice/plugin-host-compatibility.md","lastUpdated":1792725069000}'),n={name:"practice/plugin-host-compatibility.md"};function p(l,s,h,r,d,k){return i(),t("div",null,[...s[0]||(s[0]=[e(`<h1 id="插件能安装却不能保存-宿主接口与版本兼容" tabindex="-1">插件能安装却不能保存：宿主接口与版本兼容 <a class="header-anchor" href="#插件能安装却不能保存-宿主接口与版本兼容" aria-label="Permalink to &quot;插件能安装却不能保存：宿主接口与版本兼容&quot;">​</a></h1><p>插件安装成功，设置页也能打开，点保存后却没有真正生效。这里至少有三件不同的事：包管理器接受依赖范围、宿主提供对应能力、宿主接受并持久化修改。</p><p>本文取材于一个桌面主题扩展在 2026 年 9—10 月的接口迁移，核对日期为 <strong>2026-10-23</strong>。只讨论通用插件工程，不复制项目配置、素材或宿主内部实现。</p><h2 id="先把三种版本分开" tabindex="-1">先把三种版本分开 <a class="header-anchor" href="#先把三种版本分开" aria-label="Permalink to &quot;先把三种版本分开&quot;">​</a></h2><table tabindex="0"><thead><tr><th>版本</th><th>表达什么</th><th>不能代替什么</th></tr></thead><tbody><tr><td>插件版本</td><td>这次插件发布的身份</td><td>宿主版本</td></tr><tr><td>开发依赖版本</td><td>编译时使用的类型与工具</td><td>实际用户环境</td></tr><tr><td>宿主兼容范围</td><td>声明允许协作的宿主版本</td><td>真实兼容验证</td></tr></tbody></table><p>近期修复将开发依赖对齐到新的宿主 SDK，同时放宽了原先过窄的兼容声明。但仅改范围不能自动完成接口迁移；实际代码也调整了注入服务、配置命名空间和宿主侧注册方式。</p><p><code>peerDependencies</code> 用于表达与宿主或其他包的兼容关系，不能把安装检查通过当成运行验收。<a href="https://docs.npmjs.com/cli/v11/configuring-npm/package-json/#peerdependencies" target="_blank" rel="noreferrer">npm package.json</a></p><h2 id="接口名称改变-数据责任也可能改变" tabindex="-1">接口名称改变，数据责任也可能改变 <a class="header-anchor" href="#接口名称改变-数据责任也可能改变" aria-label="Permalink to &quot;接口名称改变，数据责任也可能改变&quot;">​</a></h2><p>这次迁移从旧的设置绑定接口转向宿主提供的配置表单能力。客户端按命名空间取表单，订阅权威快照，再根据当前状态判断是否能编辑和保存。</p><p>应把这条链作为一个整体核对：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>宿主注册配置定义</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>客户端取得对应命名空间</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>加载状态与可写能力</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>草稿 + 基线版本 → 提交修改</span></span>
<span class="line"><span>       ↓</span></span>
<span class="line"><span>宿主接受结果 + 权威快照 → 确认保存</span></span></code></pre></div><p>只替换一个方法名，可能留下另一端未注册、命名空间不一致或只读连接的问题。当前界面分别显示加载中、连接能力不足、保存结果未确认与冲突，而不是一律显示空设置。</p><h2 id="promise-完成不等于宿主接受" tabindex="-1">Promise 完成不等于宿主接受 <a class="header-anchor" href="#promise-完成不等于宿主接受" aria-label="Permalink to &quot;Promise 完成不等于宿主接受&quot;">​</a></h2><p>近期修复显式检查修改操作的接受结果，然后再次读取宿主快照，确认它处于可确认状态且值与提交目标相符，才更新页面基线。</p><p>通用教学伪代码可以这样表达：</p><div class="language-js vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">js</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> accepted</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> await</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">write</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(changes, baseRevision);</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">accepted) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;WRITE_REJECTED&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> current</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> form.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">snapshot</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">();</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">if</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> (</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">!</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">current.authoritative </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">||</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> !</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sameValues</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(current.value, submitted)) {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  throw</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> new</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> Error</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;WRITE_UNCONFIRMED&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>这里的 API 名称是示意。重点是把“调用结束”“写入被接受”“确认当前值”分开，而不是建议读者复制一个宿主专用函数。</p><p>当前设置页还区分草稿与已保存基线。其他窗口更新时，没有本地修改可以同步；有未保存草稿则保留草稿并提示冲突。重新加载应由用户明确选择。</p><h2 id="恢复默认值不一定是写回一组默认常量" tabindex="-1">恢复默认值不一定是写回一组默认常量 <a class="header-anchor" href="#恢复默认值不一定是写回一组默认常量" aria-label="Permalink to &quot;恢复默认值不一定是写回一组默认常量&quot;">​</a></h2><p>在分层配置里，用户值可能覆盖宿主或插件默认值。当前重置操作删除用户覆盖键，再确认这些键确实不再存在，而不是只比较界面显示是否等于默认值。</p><p>否则今天把默认值复制进用户设置，明天宿主更新默认值后，用户仍会被旧覆盖值锁住。</p><p>这是配置语义问题。只有宿主确实采用继承与覆盖模型时，删除覆盖才有这种含义；不能推广到所有设置系统。</p><h2 id="预发布版本范围尤其容易误读" tabindex="-1">预发布版本范围尤其容易误读 <a class="header-anchor" href="#预发布版本范围尤其容易误读" aria-label="Permalink to &quot;预发布版本范围尤其容易误读&quot;">​</a></h2><p>默认的 node-semver 匹配会限制预发布版本。一个范围显式包含某个版本的 <code>rc</code>，并不表示后续小版本的所有 <code>rc</code> 都会匹配。<a href="https://github.com/npm/node-semver#prerelease-tags" target="_blank" rel="noreferrer">node-semver 预发布规则</a></p><p>以下是独立合成示例，统一使用范围 <code>&gt;=1.4.0-rc.1 &lt;2.0.0</code>。结果已在本地用 node-semver 核对，未加载目标宿主：</p><table tabindex="0"><thead><tr><th>被判断版本</th><th>默认匹配结果</th></tr></thead><tbody><tr><td><code>1.4.0-rc.2</code></td><td>匹配</td></tr><tr><td><code>1.5.0-rc.1</code></td><td>不匹配</td></tr><tr><td><code>1.5.0</code></td><td>匹配</td></tr></tbody></table><p>因此，源码里“放宽了范围”与“覆盖所有桌面预发布运行时”不能画等号。建议用实际发布过的目标版本逐个测试；如果宿主采用特殊匹配参数，也要明确记录，不能默认它启用了预发布兼容选项。</p><h2 id="检查消费者真正加载的产物" tabindex="-1">检查消费者真正加载的产物 <a class="header-anchor" href="#检查消费者真正加载的产物" aria-label="Permalink to &quot;检查消费者真正加载的产物&quot;">​</a></h2><p>当前扩展将宿主入口与客户端入口分别构建，并把部分宿主共享依赖留为 external；包入口指向生成后的文件。只改源代码、不更新实际入口产物，会出现“仓库看起来修好了，用户加载的还是旧代码”。</p><p>发布前应核对源代码、类型检查、构建结果、导出路径和包内容是否一致，并确认运行时由谁提供 external 依赖。能在开发目录运行，不等于安装包包含了全部必要文件。</p><p>这里总结的是现有构建模式，没有实际执行这次扩展的安装或桌面兼容矩阵，也没有重新分发其素材。</p><h2 id="建议验证矩阵" tabindex="-1">建议验证矩阵 <a class="header-anchor" href="#建议验证矩阵" aria-label="Permalink to &quot;建议验证矩阵&quot;">​</a></h2><ul><li>[ ] 最低支持版本、常用稳定版本与目标预发布版本分别加载。</li><li>[ ] 宿主和客户端能力缺失时，给出可理解的不可用状态。</li><li>[ ] 修改被拒绝或返回不一致快照时，不显示保存成功。</li><li>[ ] 两窗口同时编辑，失败者仍保留草稿。</li><li>[ ] 重置后用户覆盖层消失，而不只是视觉值相同。</li><li>[ ] 实际打包产物中的入口、依赖与源码版本一致。</li></ul><p>延伸阅读：<a href="/practice/notes-save-lifecycle">编辑会话与本地草稿</a>、<a href="/web/frontend/build-tools">构建工具选型</a>。</p>`,34)])])}const E=a(n,[["render",p]]);export{c as __pageData,E as default};
